            writer.println(0);
        } else if (n == 1) {
            long res = (m / 6) * 6;
            long rem = m % 6;
            if (rem >= 4) {
                rem -= 3;
                res += rem * 2;
            }
            writer.println(res);
        } else if (n == 2) {
            long res = n * m;
            if (m == 3) res = 4;
            else if (m == 7) res = 12;
            writer.println(res);
